package iyuuautoseed

import (
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"os"
	"reflect"
	"testing"
)

func TestTorrentFilesSourceSeparatorRegression(t *testing.T) {
	// Exact 114-byte owned input from the actual torrentool 1.2.0 + original
	// static TorrentHelper source capture, not generated by the Go parser.
	// Source raw SHA-256: 8c86d061ef6c1ef5e3a20a85afdaa6edccd20915c8d2f3239872e638755ac246.
	const encoded = "ZDQ6aW5mb2Q1OmZpbGVzbGQ2Omxlbmd0aGkxZTQ6cGF0aGw0OnN1Yi8xOnhlZWU0Om5hbWU0OlJvb3QxMjpwaWVjZSBsZW5ndGhpMTYzODRlNjpwaWVjZXMyMDoAAAAAAAAAAAAAAAAAAAAAAAAAAGVl"
	raw, err := base64.StdEncoding.DecodeString(encoded)
	if err != nil {
		t.Fatal(err)
	}
	sum := sha256.Sum256(raw)
	if len(raw) != 114 || hex.EncodeToString(sum[:]) != "cb7d78a570a9413fb369cb07376533ed42526d530395ba325f249f9c6bede203" {
		t.Fatal("owned source input bytes changed")
	}
	// Exact source raw values: parser Root/sub/x; helper Root, [sub/x].
	folder, files := TorrentFiles(raw)
	if folder != "Root" || !reflect.DeepEqual(files, []string{"sub/x"}) {
		t.Fatalf("source separator projection: got folder=%q files=%#v; want folder=%q files=%#v", folder, files, "Root", []string{"sub/x"})
	}
}

func TestTorrentFilesRetainedSourceProjections(t *testing.T) {
	// Retain only the 25 existing source file projections. Do not execute the
	// separate 18 download/HTTP/cache scenarios in the original combined root.
	raw, err := os.ReadFile("reference/torrent-helper-oracle.json")
	if err != nil {
		t.Fatal(err)
	}
	sum := sha256.Sum256(raw)
	if hex.EncodeToString(sum[:]) != "0af5deb44232b264a2624cee6a46e93e295a5fca68fb412326723bccf34c406e" {
		t.Fatal("retained source oracle changed")
	}
	var oracle struct {
		Files []struct {
			Name    string `json:"name"`
			Content string `json:"content"`
			Result  any    `json:"result"`
		} `json:"files"`
	}
	if err := json.Unmarshal(raw, &oracle); err != nil {
		t.Fatal(err)
	}
	if len(oracle.Files) != 25 {
		t.Fatalf("retained source file projection count = %d; want 25", len(oracle.Files))
	}
	for _, row := range oracle.Files {
		t.Run(row.Name, func(t *testing.T) {
			folder, files := TorrentFiles(oracleBase64(t, row.Content))
			assertOracle(t, map[string]any{"value": []any{folder, files}}, row.Result)
		})
	}
}
